require_once dirname(__DIR__,2).'/app/bootstrap.php';require_owner();$uid=current_user_id();$ownerListings=db()->prepare('SELECT id,name FROM listings WHERE owner_user_id=:u ORDER BY name');$ownerListings->execute([':u'=>$uid]);$owned=$ownerListings->fetchAll();$allowed=array_map(fn($r)=>(int)$r['id'],$owned);$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');$listingId=(int)($_POST['listing_id']??0);if(!in_array($listingId,$allowed,true)){$errors[]='You can only manage listings assigned to your owner account.';}
 try{if(!$errors&&$action==='price_add'){$title=trim((string)($_POST['title']??''));$desc=trim((string)($_POST['description']??''));$price=trim((string)($_POST['price']??''));$unit=trim((string)($_POST['price_unit']??'per service'));if($title===''||text_len($title)>100||($price!==''&&(!is_numeric($price)||(float)$price<0||(float)$price>100000000)))throw new RuntimeException('Enter a valid service/product name and price.');db()->prepare('INSERT INTO price_items(listing_id,title,description,price,price_unit) VALUES(:l,:t,:d,:p,:u)')->execute([':l'=>$listingId,':t'=>$title,':d'=>text_substr($desc,0,500),':p'=>$price===''?null:(float)$price,':u'=>text_substr($unit,0,40)]);flash('success','Price list item added.');redirect(app_path('owner/marketplace.php#prices'));}
 elseif(!$errors&&$action==='price_delete'){$item=(int)($_POST['item_id']??0);db()->prepare('DELETE FROM price_items WHERE id=:id AND listing_id=:l')->execute([':id'=>$item,':l'=>$listingId]);flash('success','Price list item removed.');redirect(app_path('owner/marketplace.php#prices'));}
 elseif(!$errors&&$action==='slot_add'){$date=trim((string)($_POST['slot_date']??''));$time=trim((string)($_POST['slot_time']??''));$cap=max(1,min(100,(int)($_POST['capacity']??1)));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$date<date('Y-m-d')||!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/',$time))throw new RuntimeException('Choose a valid future date and time.');db()->prepare('INSERT INTO availability_slots(listing_id,slot_date,slot_time,capacity) VALUES(:l,:d,:t,:c) ON CONFLICT(listing_id,slot_date,slot_time) DO UPDATE SET capacity=MAX(availability_slots.capacity,excluded.capacity),is_active=1')->execute([':l'=>$listingId,':d'=>$date,':t'=>$time,':c'=>$cap]);flash('success','Availability slot saved.');redirect(app_path('owner/marketplace.php#availability'));}
 elseif(!$errors&&$action==='slot_toggle'){$slot=(int)($_POST['slot_id']??0);db()->prepare('UPDATE availability_slots SET is_active=1-is_active WHERE id=:id AND listing_id=:l AND booked_count=0')->execute([':id'=>$slot,':l'=>$listingId]);flash('success','Availability updated.');redirect(app_path('owner/marketplace.php#availability'));}
 elseif(!$errors&&$action==='booking_status'){$bid=(int)($_POST['booking_id']??0);$status=(string)($_POST['status']??'requested');if(!in_array($status,['confirmed','declined','cancelled','completed'],true))throw new RuntimeException('Invalid booking status.');$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare('SELECT slot_id,status,party_size FROM bookings WHERE id=:id AND listing_id=:l');$s->execute([':id'=>$bid,':l'=>$listingId]);$old=$s->fetch();if(!$old)throw new RuntimeException('Booking not found.');if($old['slot_id']&&in_array($status,['declined','cancelled'],true)&&!in_array($old['status'],['declined','cancelled'],true))$pdo->prepare('UPDATE availability_slots SET booked_count=MAX(0,booked_count-:party) WHERE id=:s')->execute([':party'=>(int)$old['party_size'],':s'=>$old['slot_id']]);if($old['slot_id']&&$status==='confirmed'&&in_array($old['status'],['declined','cancelled'],true)){$re=$pdo->prepare('UPDATE availability_slots SET booked_count=booked_count+:inc1 WHERE id=:s AND is_active=1 AND booked_count+:inc2<=capacity');$re->execute([':inc1'=>(int)$old['party_size'],':inc2'=>(int)$old['party_size'],':s'=>$old['slot_id']]);if($re->rowCount()!==1)throw new RuntimeException('The original time slot no longer has enough capacity.');}$pdo->prepare('UPDATE bookings SET status=:s,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND listing_id=:l')->execute([':s'=>$status,':id'=>$bid,':l'=>$listingId]);$pdo->commit();flash('success','Booking status updated.');redirect(app_path('owner/marketplace.php#bookings'));}
 elseif(!$errors&&$action==='quote_update'){$qid=(int)($_POST['quote_id']??0);$status=(string)($_POST['status']??'in_progress');if(!in_array($status,['in_progress','quoted','won','lost','closed'],true))throw new RuntimeException('Invalid quote status.');db()->prepare('UPDATE quote_requests SET status=:s,quoted_amount=:a,owner_notes=:n,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND listing_id=:l')->execute([':s'=>$status,':a'=>text_substr(trim((string)($_POST['quoted_amount']??'')),0,80),':n'=>text_substr(trim((string)($_POST['owner_notes']??'')),0,1000),':id'=>$qid,':l'=>$listingId]);flash('success','Quote lead updated.');redirect(app_path('owner/marketplace.php#quotes'));}
 elseif(!$errors&&$action==='enquiry_update'){$eid=(int)($_POST['enquiry_id']??0);$stage=(string)($_POST['pipeline_stage']??'new');if(!in_array($stage,['new','contacted','qualified','won','lost'],true))throw new RuntimeException('Invalid lead stage.');db()->prepare('UPDATE enquiries SET pipeline_stage=:s,owner_notes=:n,follow_up_at=:f,status=CASE WHEN :s2 IN (\'won\',\'lost\') THEN \'closed\' ELSE status END,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND listing_id=:l')->execute([':s'=>$stage,':n'=>text_substr(trim((string)($_POST['owner_notes']??'')),0,1000),':f'=>trim((string)($_POST['follow_up_at']??'')),':s2'=>$stage,':id'=>$eid,':l'=>$listingId]);flash('success','Customer lead updated.');redirect(app_path('owner/marketplace.php#leads'));}
 }catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Could not save changes. Check your fields and try again.';}
}
$in=fn($sql)=>$allowed?db()->prepare($sql):null;$bookings=[];$quotes=[];$leads=[];$prices=[];$slots=[];$messages=[];
if($allowed){$marks=implode(',',array_fill(0,count($allowed),'?'));foreach(['bookings'=>"SELECT b.*,l.name listing_name FROM bookings b JOIN listings l ON l.id=b.listing_id WHERE b.listing_id IN ($marks) ORDER BY b.booking_date DESC,b.booking_time DESC LIMIT 120",'quote_requests'=>"SELECT q.*,l.name listing_name FROM quote_requests q JOIN listings l ON l.id=q.listing_id WHERE q.listing_id IN ($marks) ORDER BY q.created_at DESC LIMIT 120",'enquiries'=>"SELECT e.*,l.name listing_name FROM enquiries e JOIN listings l ON l.id=e.listing_id WHERE e.listing_id IN ($marks) ORDER BY e.created_at DESC LIMIT 120",'price_items'=>"SELECT p.*,l.name listing_name FROM price_items p JOIN listings l ON l.id=p.listing_id WHERE p.listing_id IN ($marks) ORDER BY l.name,p.sort_order,p.title",'availability_slots'=>"SELECT a.*,l.name listing_name FROM availability_slots a JOIN listings l ON l.id=a.listing_id WHERE a.listing_id IN ($marks) AND a.slot_date>=date('now') ORDER BY a.slot_date,a.slot_time LIMIT 150"] as $key=>$sql){$st=db()->prepare($sql);$st->execute($allowed);$data=$st->fetchAll();if($key==='bookings')$bookings=$data;if($key==='quote_requests')$quotes=$data;if($key==='enquiries')$leads=$data;if($key==='price_items')$prices=$data;if($key==='availability_slots')$slots=$data;}}
